UPDATE DIARY
SET
eattime = #{eattime},
food = #{food}
WHERE petId = #{petId}
AND TO_CHAR(diaryDate, 'YYYYMMDD')=TO_CHAR(sysdate, 'YYYYMMDD')

UPDATE DIARY
SET
weight = #{weight}
WHERE petId = #{petId}
AND TO_CHAR(diaryDate, 'YYYYMMDD')=TO_CHAR(sysdate, 'YYYYMMDD')

UPDATE DIARY
SET
condition = #{condition}
WHERE petId = #{petId}
AND TO_CHAR(diaryDate, 'YYYYMMDD')=TO_CHAR(sysdate, 'YYYYMMDD')
